<?php
require '../config.php';require '../auth.php';require_admin();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='create'){$facilityId=(int)($_POST['facility_id']??0);$name=trim($_POST['court_name']??'');if($facilityId&&$name!==''){$stmt=$conn->prepare('INSERT INTO courts(facility_id,court_name) VALUES(?,?)');$stmt->bind_param('is',$facilityId,$name);if(!$stmt->execute())$error='Court name already exists for that facility.';}}elseif($action==='toggle'){$stmt=$conn->prepare('UPDATE courts SET is_active=NOT is_active WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();}elseif($action==='delete'){$stmt=$conn->prepare('DELETE FROM courts WHERE id=? AND NOT EXISTS(SELECT 1 FROM bookings WHERE court_id=?)');$stmt->bind_param('ii',$id,$id);$stmt->execute();if(!$stmt->affected_rows)$error='A court with booking history cannot be deleted; mark it inactive instead.';}}
$facilities=$conn->query('SELECT id,facility_name FROM facilities ORDER BY facility_name')->fetch_all(MYSQLI_ASSOC);$courts=$conn->query('SELECT c.*,f.facility_name FROM courts c JOIN facilities f ON f.id=c.facility_id ORDER BY f.facility_name,c.court_name')->fetch_all(MYSQLI_ASSOC);$pageTitle='Manage Courts';require 'partials/header.php';?>
<h1>Courts and Areas</h1><?php if($error):?><p class="alert alert-error"><?=htmlspecialchars($error)?></p><?php endif;?><div class="form-card" style="margin-bottom:24px"><h2>Add Court / Area</h2><form method="post"><input type="hidden" name="action" value="create"><label>Facility <select name="facility_id" required><?php foreach($facilities as $f):?><option value="<?=(int)$f['id']?>"><?=htmlspecialchars($f['facility_name'])?></option><?php endforeach;?></select></label><label>Name <input name="court_name" placeholder="e.g. Court A" required></label><button>Add</button></form></div><div class="table-wrap"><table><tr><th>Facility</th><th>Court / Area</th><th>Status</th><th>Actions</th></tr><?php foreach($courts as $c):?><tr><td><?=htmlspecialchars($c['facility_name'])?></td><td><?=htmlspecialchars($c['court_name'])?></td><td><?=$c['is_active']?'Active':'Inactive'?></td><td><form method="post" style="display:inline"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="btn btn-secondary btn-small" name="action" value="toggle">Toggle Status</button><button class="btn-small btn-danger" name="action" value="delete">Delete</button></form></td></tr><?php endforeach;?></table></div><?php require 'partials/footer.php';?>

